# Function to get state-wise colleges
def get_colleges_by_state(state_name: str, category: str = "engineering", count: int = 10):
    """Get colleges from specific state"""
    state_data = EXPANDED_STATE_COLLEGES.get(state_name, {})
    colleges = state_data.get(category, [])
    return colleges[:count]

# Function to get nearby state colleges
def get_nearby_state_colleges(state_name: str, category: str = "engineering", count: int = 5):
    """Get colleges from nearby states"""
    nearby_states = {
        "Bihar": ["Uttar Pradesh", "Jharkhand", "West Bengal"],
        "Uttar Pradesh": ["Bihar", "Madhya Pradesh", "Rajasthan", "Haryana"],
        "Rajasthan": ["Gujarat", "Madhya Pradesh", "Haryana"],
        "Maharashtra": ["Gujarat", "Madhya Pradesh", "Karnataka"],
        "Karnataka": ["Tamil Nadu", "Kerala", "Maharashtra", "Andhra Pradesh"],
        "West Bengal": ["Bihar", "Jharkhand", "Odisha", "Assam"],
    }
    
    nearby = nearby_states.get(state_name, [])
    all_colleges = []
    
    for nearby_state in nearby:
        state_colleges = get_colleges_by_state(nearby_state, category, 2)
        all_colleges.extend(state_colleges)
    
    return all_colleges[:count]
